const normalizeAbilityName=value=>String(value||'').toLowerCase().replace(/[^a-z0-9]/g,'');
const nativeAbilityAliases={animalKen:'extra-animal-kinship',artist:'art',ride:'extra-riding'};
export function abilityDefinition(key,name=''){
 const normalized=[key,name].map(normalizeAbilityName);
 const aliases=Object.fromEntries(Object.entries(nativeAbilityAliases).map(([k,v])=>[normalizeAbilityName(k),v]));
 const match=MAGE_CATALOG.abilities.find(a=>a.id===key)||MAGE_CATALOG.abilities.find(a=>normalized.includes(normalizeAbilityName(a.name))||normalized.includes(normalizeAbilityName(a.id)))||MAGE_CATALOG.abilities.find(a=>normalized.some(n=>aliases[n]===a.id));
 return match||null;
}
const nativeAbilityGuides={
 dodge:{description:'Avoid incoming attacks through timing, evasive movement and awareness. Which attacks can be avoided and the roll used depend on the system and DM.',ranks:['Avoids obvious threats when there is room to move.','Uses practiced evasive movement under pressure.','Times dodges effectively during dangerous encounters.','Anticipates attacks and evades in difficult circumstances.','Shows exceptional control and timing against demanding threats.']},
 larceny:{description:'Practical expertise with theft, locks and covert access. Tools, access and system rules determine what an attempt can accomplish.',ranks:['Understands simple locks and basic sleight of hand.','Handles routine theft or entry tasks with appropriate tools.','Plans and carries out demanding covert access tasks.','Recognizes sophisticated safeguards and handles difficult tasks.','Shows exceptional expertise with complex security and covert access.']}
};
export function traitInfo(kind,key,fallback='',name=''){
 const D=MAGE_CATALOG,G=MAGE_GUIDES;
 const definition=kind==='attribute'?null:kind==='ability'?abilityDefinition(key,name):(kind==='sphere'?D.spheres:D.backgrounds).find(x=>x.id===key);
 const canonical=definition?.id||key;
 const native=kind==='ability'?nativeAbilityGuides[normalizeAbilityName(key)]||nativeAbilityGuides[normalizeAbilityName(name)]:null;
 let ranks=kind==='attribute'?G.attributes[key]?.ranks:kind==='ability'?G.abilities[canonical]||native?.ranks:kind==='sphere'?G.spheres[canonical]:G.backgrounds[canonical];
 const general=!ranks?.length;
 if(general)ranks=['Novice: handles simple, familiar tasks.','Practiced: handles routine tasks with some confidence.','Competent: handles demanding tasks reliably.','Expert: handles difficult and unusual tasks.','Master: shows exceptional expertise in this area.'];
 let description=definition?.description||native?.description||(kind==='attribute'?G.attributes[key]?.description:'')||fallback||('Expertise in '+(name||key||'this trait')+'.');
 if(kind==='ability'&&definition?.nonCore&&key!==definition.id)description=description.replace(/^Non-core ability[^.]*\.\s*App summary:\s*/i,'');
 const aliases=[...(definition?.aliases||[])];
 if(kind==='ability'&&definition){if(definition.id==='extra-animal-kinship')aliases.push(normalizeAbilityName(name)==='animalken'?'Animal Kinship':'Animal Ken');if(name&&normalizeAbilityName(name)!==normalizeAbilityName(definition.name))aliases.push(definition.name);}
 return {nonCore:!!definition?.nonCore&&key===definition.id,catalogId:canonical,info:[description,aliases.some(alias=>!description.toLowerCase().includes(alias.toLowerCase()))?'Also covers: '+[...new Set(aliases)].filter(alias=>!description.toLowerCase().includes(alias.toLowerCase())).join(', '):'',(general?'General app guidance — DM defines the exact scope.\n':'')+'Dot meanings:\n'+ranks.map((s,i)=>(i+1)+': '+s).join('\n'),kind==='background'?'Qualitative guide; exact benefits require the rules and DM agreement.':''].filter(Boolean).join('\n\n'),ranks,generalGuidance:general};
}
export function requiredSpecialties(actor){
 const out=[];
 for(const [key,a] of Object.entries(actor.system?.attributes||{}))if(Number(a.value)>=4&&!String(a.speciality||'').trim())out.push({kind:'attribute',key,name:MAGE_CATALOG.attrNames[key]||key,value:Number(a.value),speciality:''});
 for(const item of actor.items||[])if(item.type==='Ability'&&Number(item.system?.value)>=4&&!String(item.system?.speciality||'').trim())out.push({kind:'ability',key:item.system.id,itemId:item.id,name:item.name,value:Number(item.system.value),speciality:''});
 return out;
}
